begin;
create extension if not exists pgtap with schema extensions;
set search_path = public, extensions;
select no_plan();
insert into auth.users(id,email) values
 ('97000000-0000-0000-0000-000000000001','interaction-author@test.dev'),
 ('97000000-0000-0000-0000-000000000002','interaction-a@test.dev'),
 ('97000000-0000-0000-0000-000000000003','interaction-b@test.dev');
insert into private.posts(author_id,type,content) values
 ('97000000-0000-0000-0000-000000000001','post','댓글 테스트 첫번째 글'),
 ('97000000-0000-0000-0000-000000000001','post','댓글 테스트 두번째 글');
select set_config('test.post',(select id::text from private.posts where content='댓글 테스트 첫번째 글'),true);
select set_config('test.second',(select id::text from private.posts where content='댓글 테스트 두번째 글'),true);
insert into private.posts(author_id,type,content,ends_at) values ('97000000-0000-0000-0000-000000000001','vote','댓글 테스트 투표글',now()+interval '24 hours');
select set_config('test.vote',(select id::text from private.posts where content='댓글 테스트 투표글'),true);
set local role anon;
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,'댓글',gen_random_uuid())$$,'42501',null,'비회원 댓글 등록 불가');
select throws_ok($$select public.update_comment(1,'댓글')$$,'42501',null,'비회원 수정 불가');
select throws_ok($$select public.delete_comment(1)$$,'42501',null,'비회원 삭제 불가');
select throws_ok($$select public.set_community_like(current_setting('test.post')::bigint,true)$$,'42501',null,'비회원 좋아요 불가');
select throws_ok($$select public.set_community_like(current_setting('test.vote')::bigint,true)$$,'42501',null,'비회원 투표글 좋아요 불가');
set local role authenticated;
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,'댓글',gen_random_uuid())$$,'42501','not_authenticated','JWT 없는 쓰기 거부');
set local request.jwt.claims = '{"sub":"97000000-0000-0000-0000-000000000002","role":"authenticated"}';
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,'',gen_random_uuid())$$,'22023','invalid_comment_content','빈 댓글 거부');
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,E' \n\t',gen_random_uuid())$$,'22023','invalid_comment_content','공백 댓글 거부');
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,U&'\00A0\3000',gen_random_uuid())$$,'22023','invalid_comment_content','Unicode 공백 댓글 거부');
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,repeat('가',31),gen_random_uuid())$$,'22023','invalid_comment_content','31자 거부');
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,null,gen_random_uuid())$$,'22023','invalid_comment_content','null 본문 거부');
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,'댓글',null)$$,'22023','invalid_request_id','재시도 키 필요');
select set_config('test.comment',public.create_comment(current_setting('test.post')::bigint,'첫 댓글','97000000-0000-0000-0000-000000000011')->>'id',true);
select is(public.get_community_comments(current_setting('test.post')::bigint)->0->>'anon_number','1','첫 참여자 디기 1');
select is(public.get_community_comments(current_setting('test.post')::bigint)->0->>'is_mine','true','내 댓글 상태');
select ok(not (public.get_community_comments(current_setting('test.post')::bigint)->0 ? 'author_id'),'댓글 응답은 UUID 미포함');
select is(public.create_comment(current_setting('test.post')::bigint,'첫 댓글','97000000-0000-0000-0000-000000000011')->>'id',current_setting('test.comment'),'동일 요청 재시도는 같은 댓글');
select is(jsonb_array_length(public.get_community_comments(current_setting('test.post')::bigint)),1,'응답 유실 재시도 중복 없음');
select is(public.create_comment(current_setting('test.post')::bigint,'두 번째 댓글',gen_random_uuid())->>'anon_number','1','같은 글에서 같은 번호');
select is(public.create_comment(current_setting('test.second')::bigint,'다른 글 댓글',gen_random_uuid())->>'anon_number','1','다른 글 번호는 새로 할당');
select throws_ok($$select public.create_comment(current_setting('test.second')::bigint,'다른 글 댓글','97000000-0000-0000-0000-000000000011')$$,'22023','invalid_request_id','키를 다른 게시글에서 재사용하지 못함');
select lives_ok($$select public.create_comment(current_setting('test.post')::bigint,repeat('👍🏽',30),gen_random_uuid())$$,'피부색 이모지 30자 허용');
select is(public.create_comment(current_setting('test.post')::bigint,U&'e\0301',gen_random_uuid())->>'content','é','NFC 정규화');
select is(public.create_comment(current_setting('test.post')::bigint,E'첫줄\r\n\r\n끝줄',gen_random_uuid())->>'content',E'첫줄\n\n끝줄','CRLF를 줄바꿈 1자로 정규화하고 연속 줄바꿈 유지');
select lives_ok($$select public.create_comment(current_setting('test.post')::bigint,repeat('가',29)||E'\r\n',gen_random_uuid())$$,'29자+CRLF는 30자');
select is(public.update_comment(current_setting('test.comment')::bigint,'수정한 댓글')->>'content','수정한 댓글','내 댓글 수정');
select lives_ok($$select public.update_comment(current_setting('test.comment')::bigint,'수정한 댓글')$$,'동일 본문 저장도 허용');
select throws_ok($$select public.update_comment(current_setting('test.comment')::bigint,repeat('가',31))$$,'22023','invalid_comment_content','수정도 길이 검증');
select is(public.set_community_like(current_setting('test.post')::bigint,true)->>'like_count','1','좋아요 등록');
select is(public.set_community_like(current_setting('test.post')::bigint,true)->>'like_count','1','등록 재시도는 1개 유지');
select is(public.get_community_post(current_setting('test.post')::bigint)->>'is_liked','true','상세 본인 좋아요 상태 반영');
select is(public.set_community_like(current_setting('test.vote')::bigint,true)->>'like_count','1','투표글 좋아요 등록');
select is(public.set_community_like(current_setting('test.vote')::bigint,true)->>'like_count','1','투표글 좋아요 재시도 중복 없음');
select is(public.get_community_post(current_setting('test.vote')::bigint)->>'is_liked','true','투표글 상세 좋아요 상태');
select is((select item->>'like_count' from jsonb_array_elements(public.get_community_feed('all')) item where item->>'id'=current_setting('test.vote')),'1','전체 목록에 투표글 좋아요 집계');
select ok(exists(select 1 from jsonb_array_elements(public.get_my_community_activity('liked')) item where item->'post'->>'id'=current_setting('test.vote')),'좋아요 활동에 투표글 포함');
select is(public.set_community_like(current_setting('test.vote')::bigint,false)->>'like_count','0','투표글 좋아요 취소');
select is(public.get_community_post(current_setting('test.vote')::bigint)->>'is_liked','false','투표글 취소 후 상태');
select ok(not exists(select 1 from jsonb_array_elements(public.get_my_community_activity('liked')) item where item->'post'->>'id'=current_setting('test.vote')),'취소한 투표글은 좋아요 활동에서 제외');
select throws_ok($$select public.set_community_like(current_setting('test.post')::bigint,null)$$,'22023','invalid_like_state','null 상태 거부');
select lives_ok($$select public.create_comment(current_setting('test.vote')::bigint,'투표와 독립인 댓글',gen_random_uuid())$$,'투표 참여 없이 댓글 등록 허용');
reset role;
set local request.jwt.claims = '{"sub":"97000000-0000-0000-0000-000000000001","role":"authenticated"}';
set local role authenticated;
select set_config('test.author_comment',public.create_comment(current_setting('test.post')::bigint,'글쓴이 댓글',gen_random_uuid())->>'id',true);
select is(public.create_comment(current_setting('test.post')::bigint,'글쓴이 또 댓글',gen_random_uuid())->>'is_post_author','true','글쓴이 라벨');
select is(public.create_comment(current_setting('test.post')::bigint,'글쓴이 세 번째 댓글',gen_random_uuid())->>'anon_number',null,'글쓴이에게 번호 없음');
select throws_ok($$select public.update_comment(current_setting('test.comment')::bigint,'타인 수정')$$,'42501','comment_not_found','글쓴이도 타인 댓글 수정 불가');
select throws_ok($$select public.delete_comment(current_setting('test.comment')::bigint)$$,'42501','comment_not_found','글쓴이도 타인 댓글 삭제 불가');
reset role;
set local request.jwt.claims = '{"sub":"97000000-0000-0000-0000-000000000003","role":"authenticated"}';
set local role authenticated;
select is(public.create_comment(current_setting('test.post')::bigint,'다른 사용자 댓글',gen_random_uuid())->>'anon_number','2','글쓴이를 제외하고 다음 번호 할당');
select is(public.set_community_like(current_setting('test.post')::bigint,true)->>'like_count','2','두 사용자의 유효 좋아요 집계');
reset role;
set local request.jwt.claims = '{"sub":"97000000-0000-0000-0000-000000000002","role":"authenticated"}';
set local role authenticated;
select is(public.set_community_like(current_setting('test.post')::bigint,false)->>'like_count','1','내 좋아요만 취소');
select is(public.set_community_like(current_setting('test.post')::bigint,false)->>'like_count','1','취소 재시도 안전');
select lives_ok($$select public.delete_comment(current_setting('test.comment')::bigint)$$,'본인 댓글 삭제');
select lives_ok($$select public.delete_comment(current_setting('test.comment')::bigint)$$,'삭제 재시도 안전');
select ok(not exists(select 1 from jsonb_array_elements(public.get_community_comments(current_setting('test.post')::bigint)) c where c->>'id'=current_setting('test.comment')),'삭제 댓글은 목록에서 제외');
select is(public.create_comment(current_setting('test.post')::bigint,'지운 뒤 다시 댓글',gen_random_uuid())->>'anon_number','1','삭제해도 기존 번호 유지');
select throws_ok($$select public.update_comment(current_setting('test.comment')::bigint,'삭제된 댓글 수정')$$,'42501','comment_not_found','삭제 댓글 수정 불가');
select throws_ok($$select private.community_comment_json(current_setting('test.author_comment')::bigint)$$,'42501',null,'내부 serializer 호출 차단');
select throws_ok($$select private.lock_community_post_for_write(current_setting('test.post')::bigint)$$,'42501',null,'잠금 helper 직접 호출 차단');
select throws_ok($$select * from private.post_likes$$,'42501',null,'원시 좋아요 접근 차단');
select throws_ok($$update private.comments set content='직접 수정'$$,'42501',null,'원시 댓글 변경 차단');
reset role;
update public.profiles set status='community_restricted',restricted_until=now()+interval '7 days' where id=auth.uid();
set local role authenticated;
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,'제한 계정 댓글',gen_random_uuid())$$,'42501','community_restricted','제재 등록 차단');
select throws_ok($$select public.update_comment(current_setting('test.comment')::bigint,'제한 계정 수정')$$,'42501','community_restricted','제재 수정 차단');
select throws_ok($$select public.delete_comment(current_setting('test.comment')::bigint)$$,'42501','community_restricted','제재 댓글 삭제 차단');
select throws_ok($$select public.set_community_like(current_setting('test.post')::bigint,true)$$,'42501','community_restricted','제재 좋아요 차단');
select throws_ok($$select public.set_community_like(current_setting('test.vote')::bigint,true)$$,'42501','community_restricted','제재 투표글 좋아요 차단');
reset role;
update public.profiles set restricted_until=now()-interval '1 second' where id=auth.uid();
set local role authenticated;
select lives_ok($$select public.create_comment(current_setting('test.post')::bigint,'제한 만료 댓글',gen_random_uuid())$$,'만료된 제한은 쓰기 허용');
reset role;
insert into private.user_blocks(blocker_id,blocked_id) values (auth.uid(),'97000000-0000-0000-0000-000000000001');
set local role authenticated;
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,'차단 댓글',gen_random_uuid())$$,'42501','post_not_found','차단 작성자의 글에 등록 불가');
select throws_ok($$select public.set_community_like(current_setting('test.post')::bigint,true)$$,'42501','post_not_found','차단 작성자의 글에 좋아요 불가');
select throws_ok($$select public.set_community_like(current_setting('test.vote')::bigint,true)$$,'42501','post_not_found','차단 작성자의 투표글 좋아요 불가');
reset role;
delete from private.user_blocks where blocker_id=auth.uid();
update private.posts set hidden_at=now() where id=current_setting('test.vote')::bigint;
set local role authenticated;
select throws_ok($$select public.create_comment(current_setting('test.vote')::bigint,'숨긴 글 댓글',gen_random_uuid())$$,'42501','post_not_found','숨긴 글 등록 불가');
select throws_ok($$select public.set_community_like(current_setting('test.vote')::bigint,true)$$,'42501','post_not_found','숨긴 투표글 좋아요 불가');
reset role;
set local request.jwt.claims = '{"sub":"97000000-0000-0000-0000-000000000001","role":"authenticated"}';
set local role authenticated;
select lives_ok($$select public.delete_community_post(current_setting('test.post')::bigint)$$,'부모 글 삭제');
select throws_ok($$select public.create_comment(current_setting('test.post')::bigint,'삭제 글 댓글',gen_random_uuid())$$,'42501','post_not_found','삭제 글 등록 불가');
select throws_ok($$select public.update_comment(current_setting('test.author_comment')::bigint,'삭제 글 수정')$$,'42501','post_not_found','삭제 글의 댓글 수정 불가');
select throws_ok($$select public.set_community_like(current_setting('test.post')::bigint,true)$$,'42501','post_not_found','삭제 글 좋아요 불가');
select throws_ok($$select public.create_comment(999999999,'없는 글 댓글',gen_random_uuid())$$,'42501','post_not_found','없는 글 등록 불가');
select * from finish();
rollback;
